package com.smartmanager.nativeapp;
import android.content.*;import android.util.Base64;import java.nio.charset.StandardCharsets;import java.util.*;
/** Multiple non-secret templates with safe deletion of non-default entries. */
public final class TemplateStore {private final SharedPreferences p;public TemplateStore(Context c){p=c.getSharedPreferences("card_templates",Context.MODE_PRIVATE);}public synchronized List<CardTemplate> all(){ArrayList<CardTemplate>o=new ArrayList<>();for(String l:p.getString("archive","").split("\\n"))try{String[]x=l.split("\\|",-1);if(x.length==13)o.add(new CardTemplate(x[0],dec(x[1]),dec(x[2]),Integer.parseInt(x[3]),Integer.parseInt(x[4]),Integer.parseInt(x[5]),Integer.parseInt(x[6]),Integer.parseInt(x[7]),Integer.parseInt(x[8]),"1".equals(x[9]),"1".equals(x[10]),"1".equals(x[11]),"1".equals(x[12])));}catch(Exception ignored){}if(o.isEmpty())o.add(new CardTemplate("default","Smart Manager A4","",595,842,6,2,26,9,true,true,true,true));return o;}public synchronized CardTemplate get(){String id=p.getString("selected","default");for(CardTemplate t:all())if(t.id.equals(id))return t;return all().get(0);}public synchronized boolean select(String id){for(CardTemplate t:all())if(t.id.equals(id))return p.edit().putString("selected",id).commit();return false;}public synchronized boolean remove(String id){if("default".equals(id))return false;ArrayList<CardTemplate>a=new ArrayList<>(all());a.removeIf(t->t.id.equals(id));if(a.size()==all().size()||a.isEmpty())return false;return write(a,"default");}public synchronized boolean save(CardTemplate t){ArrayList<CardTemplate>a=new ArrayList<>(all());boolean f=false;for(int i=0;i<a.size();i++)if(a.get(i).id.equals(t.id)){a.set(i,t);f=true;}if(!f)a.add(t);return write(a,t.id);}private boolean write(List<CardTemplate>a,String selected){StringBuilder b=new StringBuilder();for(CardTemplate x:a)b.append(x.id).append('|').append(enc(x.name)).append('|').append(enc(x.imageUri)).append('|').append(x.paperW).append('|').append(x.paperH).append('|').append(x.rows).append('|').append(x.columns).append('|').append(x.margin).append('|').append(x.gap).append('|').append(x.showUser?1:0).append('|').append(x.showPassword?1:0).append('|').append(x.showProfile?1:0).append('|').append(x.showSerial?1:0).append('\n');return p.edit().putString("archive",b.toString()).putString("selected",selected).commit();}private static String enc(String s){return Base64.encodeToString(s.getBytes(StandardCharsets.UTF_8),2);}private static String dec(String s){return new String(Base64.decode(s,2),StandardCharsets.UTF_8);}}
